namespace BoatsNBeasts.Core;

public enum Shipmate { None, Lio, Vara, Nell }
public sealed record CrewWatch(string Title,string Scene,string Near,string Far,string NearResult,string FarResult);

public static class CrewWatches
{
    public static readonly int[] Thresholds=[0,1,3,6,8,11,14,16];
    public static string Token(Shipmate mate) => mate switch
    {
        Shipmate.Lio=>"The spare line",Shipmate.Vara=>"Vara’s thermos",Shipmate.Nell=>"The quiet bell",_=>""
    };
    public static string Help(Shipmate mate)=>mate switch
    {
        Shipmate.Lio=>"Lio catches up to three nearby enemies on his spare line.",Shipmate.Vara=>"Vara repairs 45 hull or restores four health ashore.",
        Shipmate.Nell=>"Nell interrupts incoming fire or attack warnings and gives the crew a short safe crossing.",_=>""
    };
    public static CrewWatch[] For(Shipmate mate)=>mate switch {Shipmate.Lio=>Diver,Shipmate.Vara=>Founder,_=>Keeper};
    static readonly CrewWatch[] Diver=[
        new("A cup with no bottom","Lio turns a tin cup over in his hands. “A dive bell in miniature. Put it in the water straight and a beetle can breathe inside. Tilt it and it tells you everything at once.”","Try for the beetle","Tilt it and listen","A little beetle rides the air up like a passenger in a lift. Lio salutes it with two fingers.","The bubbles come up in different voices. One sounds remarkably like Nell sending late boats home."),
        new("The part that comes back","Lio has cut his old salvage rope in two. “A crew that shares one good line might find both ends in the water at once.” He pushes one coil across.","Ask him to teach the splice","Offer a line from your own kit","He puts his hands over yours only once. By the third splice he trusts you to cut the loose ends.","He works your line into his until the two colors make a braid. “Now I'll know who I'm hauling.”"),
        new("Dark on the good side","At sunset Lio hangs a little jar over the gunwale. There is no wick inside. “If you take a bright light down, every creature that minds your business can see you coming.”","Sit in the dark with him","Drop one spark into the jar","By the time the first plankton lights up you can see all the way to the mud. Lio puts one bare foot in for company.","The spark draws an inquisitive shrimp. It hangs in front of the glass like a comma waiting for the next word."),
        new("One chair too many","Lio invites Vara and Oren to supper and sets four chairs. “If we put two people at a table with only their quarrel, the quarrel gets a chair as well.”","Stay for the meal","Send Pip with a great deal of bread","They argue over who gets the burnt bit. When it is gone they have found a better argument and Lio gets another plate.","Pip and the bread take up two chairs. By the time she finishes her story everybody has forgotten which seat was intended for the quarrel."),
        new("What holds a quay still","The harbor has walked six feet overnight. Lio slips underneath with a piece of chalk and comes out with all his hair pointing in one direction.","Ask what he saw","Lend him a comb","“Feet. Not legs, exactly. An old island takes lots of little steps. Like somebody getting up for tea without waking their wife.”","He uses the comb to draw the tracks in the sand. When the tide takes them, the comb still knows how far apart the toes were."),
        new("A ladder for the next diver","A new diver would like Lio's job. He makes her a ladder. The last rung is beyond either of their reach.","Hold the ladder","Let her move the rung","She makes it most of the way up and looks down. Lio is beaming at the wrong end, glad to have someone else up there.","She saws it off and fits it two feet lower. Lio starts an argument about tools. By breakfast it is her ladder."),
        new("No need of the bottom","Lio's wrist aches when the depth changes. He has left his helmet on a high shelf. The new diver puts it down beside the door every morning.","Ask which dive he misses","Invite him to take the helm","“The first one I can't remember. I wish I could go down without knowing what a thing is called.” He takes a child out with him the next day.","He steers with two fingers and calls every crossing hazard by its shape underneath. The crew learns three new words for rock."),
        new("What the tide keeps","Lio puts the battered tin cup on the pier beside a calf. The calf covers it with one foot.","Wait for the tide","Trade a turnip for the cup","At high tide a small bubble escapes from under the foot. Lio laughs so hard the calf lifts its foot to find the noise.","The calf takes the turnip and leaves the cup upside down. Under it is a beetle with excellent sea legs.")
    ];
    static readonly CrewWatch[] Founder=[
        new("The spoon with a flat side","Vara's brass ladle is visibly crooked. She holds it to the edge of the bell frame. The dents fit.","Ask about the first dent","Help polish the high spots","“I had a hammer, but it wasn't supper time.” She gives you a spoon and tells you to listen to the frame before you strike.","The dents go dark and the high spots shine. Vara turns it in her fingers. “Now I can see where my hand belongs.”"),
        new("Something for the last watch","Vara has made a flask with two tin walls. The first watch has drunk all the broth before the last can try it.","Save the next serving","Teach everyone to fill it","Vara ties a blue thread around its neck. Anything with that thread belongs to somebody who hasn't had a turn.","The deck smells of onions three nights running. Everyone has an opinion about the proper amount. Vara keeps all three recipes inside the lid."),
        new("A recognizable hand","Vara knows her brother's handwriting by his R. “I told him it looked like a man trying to climb out of a bath.” Her thumb covers the rest of the letter.","Let her read it alone","Read the ordinary lines aloud","You stay on the other side of the stove. After a while she starts laughing. The letter ends with a shopping list.","You get through potatoes and soap before she takes it back to do Oren's voice. His bath has come a long way."),
        new("Before the soup boils","Oren and Vara both turn up early to make soup. There is only enough room for one person at the chopping board.","Find another board","Ask them to trade after each onion","They work with their backs to each other. The first sentence passes across the stove without either of them having to look up.","By the third onion they both have excellent reasons for the state of their eyes. Vara hands him a dry cloth."),
        new("A place for the ringing","The frame is bolted to moving ground. Every step the island takes risks a false alarm. Vara drapes her coat over the bell.","Ask the island to give warning","Help hang a soft clapper","Lio puts a cup against the ground and raises one hand just before the step. Vara has rarely been this delighted to see someone spill tea.","She wraps the clapper with a strip of old sail. The bell has two voices now, one for coming home and one for leaving."),
        new("The little vice","A child brings a bent nail to the forge. Vara has spent the afternoon on a ship's anchor. She shuts the big vice and opens the little one.","Hold the nail steady","Stand back and watch","The child strikes it square on the first try. Vara puts the straight nail in your palm as though it were a commission from an admiral.","The nail turns out to be a little hook for a coat. Vara makes another and hangs both within a child's reach."),
        new("Brother metal","Vara and Oren are deciding which story to tell about the years he was gone. They cannot make either version fit the same mold.","Give them two molds","Leave a gap in one casting","On the shelf the two castings cast one shadow. Vara leaves room behind them for a lamp.","Light comes through the little gap. Oren has started slipping notes through it about what he remembers next."),
        new("A socket for a spoon","The bell founder has finished her last commission. A young island has grown a small round hole in the rock at its shore.","Fit the ladle there","Ask what the calf wants","The ladle sits in it like a little lighthouse. The first travelers use it to drink fresh rainwater.","The calf pushes the handle against the pier and gives the smallest answering ring. Vara keeps her hand on the handle a long time.")
    ];
    static readonly CrewWatch[] Keeper=[
        new("The first empty line","Nell draws a line across a blank sheet. “Once you put a heading on there it becomes surprisingly hard to see anything else.”","Start with the weather","Leave room above it","She writes Damp. A child comes in dripping up to the eyebrows. The weather immediately needs a bigger word.","Somebody later draws a little boat above the line. Nell pencils in a gull and has the grace to rub it out when the boat turns out to be a cake."),
        new("A ringing nobody owes","Nell has filed one tooth off the toll bell. It makes a low sound that carries very well through fog. “It ought to mean take one breath.”","Practice calling the watch","Ask her to ring it for herself","The first ringing startles the cook. By the third the whole galley exhales together. Nell sets the quiet bell beside the chart.","She rings it once and sits with her hands folded. For the first time all morning nobody asks her for an entry."),
        new("The proper spelling of home","Three households have three ways of spelling the same bank. Nell begins to sharpen a red pencil, then puts the knife away.","Give each spelling a page","Ask the ferryman how it sounds","The children make cross-references shaped like little bridges. Anyone can walk from one spelling to the next.","The ferryman sings it through his teeth. Nell sets down the notes and lets the letters look after themselves."),
        new("A witness in an apron","Pip has put a witness statement on the back of a recipe. Nell measures the space in the book. There is room for the statement or the ingredients.","Fold out the page","Cook the recipe together","The foldout gets a gravy stain on its first evening. Nell marks the stain as evidence of excellent dumplings.","While the onions catch, Pip tells the story again. This time Nell remembers what made the cook put down her knife."),
        new("What doesn't belong on a map","The baby reef has moved out of its square. Nell puts an eggcup where it used to be.","Draw a little arrow","Take the eggcup outside","The next day it needs two arrows. By midweek Nell has made her first moving picture in the corner of the ledger.","The calf puts one foot into the eggcup. It goes to sleep. Nell writes a perfectly accurate chart of the next half hour."),
        new("The price of a quiet room","The sick need sleep. The calf underneath their beds needs to wake up. Nell sets the little bell where both of them can reach it.","Take the first silent watch","Let the patients set the signal","Everybody agrees the island sighed at midnight. Nobody agrees about what it dreamed. Nell leaves a blank where the rest would have gone.","The smallest patient invents a knock nobody else can make. The shoal answers anyway, with a sound like a pillow turning over."),
        new("An ordinary complaint","Toma asks if there is space in the public ledger for a bad dinner. Nell looks at the shelves of testimony about disasters.","Bring the galley book","Offer her an empty page","The complaint is about a dinner left too long on the stove. The next entry is the recipe. Toma knows it by heart.","Toma writes the complaint in one line. The rest is about the person who cooked it. Nell gives her the space."),
        new("The book afloat","Nell tries the ledger in a tub. It floats for a moment and then gets on with sinking. “There goes my best idea for a lifeboat.”","Bring a pair of oilskins","Give her a new blank book","They fit round it like a hull. The book makes a short voyage with three sugared almonds as passengers.","The old ledger dries by the stove. The first entry in the new book is a useful observation about the buoyancy of three hundred damp pages.")
    ];
}
